/**
 * The error code registry (agent operator contract v1, A2). Every literal
 * code thrown in `src/` has one entry here: its class (which derives the CLI
 * exit code and `retryable`), a one-sentence meaning, and optionally a
 * default suggestion, a default fix (diagnostic reads only), reasons, a docs
 * anchor and the frozen legacy wire value. `docs/guides/error-codes.md` is
 * generated from this table (`bun run build:error-codes`), and
 * `test/error-catalogue.test.ts` walks the source AST so an unregistered code
 * fails CI.
 *
 * Adding a code: add one entry (snake_case, no transport prefix), then run
 * `bun run build:error-codes`. Entries default their docs to
 * `docs/guides/error-codes.md#<code>`.
 */
import type { Action, Actor, Effect, ErrorClass } from './agent-output.ts';
import { FENCE_REASON_CODES } from './fence-repair/reasons.ts';

export interface CodeEntry {
  class: ErrorClass;
  /** What happened, one sentence. */
  summary: string;
  /** Why it happens / what it protects. */
  why?: string;
  /** Closed vocabulary for `reason` when one code covers several causes. */
  reasons?: readonly string[];
  /**
   * Tombstones of reasons nothing emits any more (reason → the release that retired it); a receipt an older build wrote may
   * still carry one, so it stays explained here, and it never returns to `reasons`.
   */
  retired_reasons?: Readonly<Record<string, string>>;
  /**
   * A reason whose next step differs in kind from the code's (a lock that waiting never frees needs the user, not a retry):
   * its class and exit replace the code's on the envelope and the CLI exit. Every key is also in `reasons`.
   */
  reason_overrides?: Readonly<Record<string, { class: ErrorClass; exit?: number }>>;
  /** Repo-relative anchor; default `docs/guides/error-codes.md#<code>`. */
  docs?: string;
  /** Default prose suggestion when a site supplies none. */
  suggestion?: string;
  /**
   * Default fix template: read-only diagnostics only (scanner-checked).
   * `{slug}`, `{source_id}`, `{request_id}`, `{operation}` placeholders are
   * filled from envelope/receipt fields at render time; an unfillable
   * template is dropped, never rendered with a placeholder.
   */
  fix?: Action;
  effects?: readonly Effect[];
  actor?: Actor;
  /** The code this one replaced (documented in error-codes.md "Legacy `error` values"). */
  renamed_from?: string;
  /** Frozen v1 `error` wire value some sites keep for this canonical code. */
  legacy_error?: string;
  /** CLI exit code; default derives from class (1). */
  exit?: number;
  retryable?: boolean;
  /**
   * The release that retired this code: nothing emits it any more, but receipts and ledger rows an older build wrote still
   * carry it, so the entry stays and `gbrain errors <code>` still answers. Its fix names the current path, never a retired
   * key or flag (`test/error-registry-retired.test.ts`).
   */
  retired_in?: string;
}

